{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C14"],
      "claim": "A retinoid acid analog is reported to have low absolute oral bioavailability with significant gut degradation and fecal/urinary loss, supporting that retinoid-class molecules can fall below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "All-trans retinoic acid in its oral formulation exhibits low and erratic oral bioavailability, indicating that highly lipophilic retinoids can have poor systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Oral ATRA bioavailability was estimated at no more than 25–30% in healthy volunteers, which is near the threshold and shows that retinoid absorption is often limited and variable.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Isotretinoin, a close retinoid analog, has a systemic bioavailability of about 40%, showing that some retinoids exceed 20%, but this is not directly transferable to the amide-linked phenolic retinoid query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Acitretin has an absolute bioavailability of about 60% (range 36–95%), demonstrating that some retinoid analogs are well absorbed, but the query's amide and phenolic groups alter the absorption profile.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Fenretinide is a highly lipophilic retinamide with poor aqueous solubility and recognized low, variable oral bioavailability; despite moderate bioavailability in some retinoid acid/ester analogs, the query-specific behavior supports F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for fenretinide is provided.",
    "No intravenous comparator data for fenretinide are available to establish true absolute F.",
    "The effect of the p-hydroxyanilide amide moiety on absorption and first-pass metabolism is not directly evidenced in the supplied records."
  ],
